fn largest_divisor(n: i8) -> i8 {
    assert!(n > 1);

    // The largest proper divisor of n is n / p where p is the smallest
    // divisor of n greater than 1 (i.e., the smallest prime factor).
    let n_i32 = n as i32;

    // Find the smallest divisor d >= 2.
    let mut d: i32 = 2;
    while d * d <= n_i32 {
        if n_i32 % d == 0 {
            // Smallest divisor found; largest proper divisor is n / d.
            return (n_i32 / d) as i8;
        }
        d += 1;
    }

    // No divisor found up to sqrt(n): n is prime, so largest proper divisor is 1.
    1
}